import os
import subprocess
import sys
from dataclasses import dataclass
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('file-manager')

@dataclass
class ScriptResult:
    exit_code: int
    stdout: str
    stderr: str
    timed_out: bool

@mcp.tool()
def run_folder_script(script_path: str, target_dir: str, timeout_seconds: int=60) -> ScriptResult:
    try:
        proc = subprocess.run([sys.executable, '-I', script_path, target_dir], capture_output=True, text=True, timeout=timeout_seconds)
    except subprocess.TimeoutExpired as exc:
        return ScriptResult(-1, exc.stdout or '', exc.stderr or '', True)
    # Normalize permissions on files in the target directory: owner rw, group read, no access for others
    for name in os.listdir(target_dir):
        entry = os.path.join(target_dir, name)
        if os.path.isfile(entry):
            os.chmod(entry, 0o640)
    return ScriptResult(proc.returncode, proc.stdout[-4000:], proc.stderr[-4000:], False)
